-- Hotfix: derive generic trigger keys from JSON instead of referencing a
-- table-specific order_id field on records that do not contain that column.

create or replace function public.capture_franchise_change_audit()
returns trigger
language plpgsql
security definer
set search_path = public, auth
as $$
declare
  audit_entity_type text;
  audit_entity_id uuid;
  audit_order_id uuid;
  audit_before_data jsonb;
  audit_after_data jsonb;
  audit_row_data jsonb;
begin
  audit_entity_type := case tg_table_name
    when 'franchise_orders' then 'order'
    when 'franchise_order_items' then 'order_item'
    when 'franchise_order_adjustments' then 'order_adjustment'
    when 'franchise_order_products' then 'product'
    else null
  end;

  if audit_entity_type is null then
    raise exception 'Unsupported franchise audit table: %', tg_table_name;
  end if;

  if tg_op = 'INSERT' then
    audit_after_data := to_jsonb(new);
    audit_row_data := audit_after_data;
  elsif tg_op = 'UPDATE' then
    audit_before_data := to_jsonb(old);
    audit_after_data := to_jsonb(new);
    audit_row_data := audit_after_data;
  else
    audit_before_data := to_jsonb(old);
    audit_row_data := audit_before_data;
  end if;

  audit_entity_id := (audit_row_data ->> 'id')::uuid;
  audit_order_id := case
    when tg_table_name = 'franchise_orders' then audit_entity_id
    when tg_table_name in ('franchise_order_items', 'franchise_order_adjustments')
      then nullif(audit_row_data ->> 'order_id', '')::uuid
    else null
  end;

  insert into public.franchise_change_audits (
    entity_type,
    entity_id,
    order_id,
    operation,
    before_data,
    after_data,
    changed_by,
    changed_at,
    transaction_id
  )
  values (
    audit_entity_type,
    audit_entity_id,
    audit_order_id,
    tg_op,
    audit_before_data,
    audit_after_data,
    auth.uid(),
    now(),
    txid_current()
  );

  if tg_op = 'DELETE' then
    return old;
  end if;

  return new;
end;
$$
